 @org.springframework.boot.test.context.TestConfiguration static class Notifications {
  final List<UUID> paid=new CopyOnWriteArrayList<>(), late=new CopyOnWriteArrayList<>();
  @org.springframework.transaction.event.TransactionalEventListener public void paid(com.eema.backend.event.BookingPaidEvent event){paid.add(event.bookingId());}
  @org.springframework.transaction.event.TransactionalEventListener public void late(com.eema.backend.event.LatePaymentRefundInitiatedEvent event){late.add(event.bookingId());}
 }
